with store_stats as (select store_id, round((100 * sum(case when status = 'CANCELLED' then 1 else 0 end)) / count(*), 1) as pct_cancelled from orders where store_id in (10, 31, 34) group by store_id) select stores.id, stores.sqft, store_stats.pct_cancelled from stores inner join store_stats on stores.id = store_stats.store_id where store_stats.pct_cancelled >= 68 order by sqft desc, id limit 50;
